 std::optional<Fixture> matured;for(bool is_exit:{false,true}){if(is_exit)matured.emplace(fixture(512));const auto& f=is_exit?*matured:early;test_stage=is_exit?"fixed-exit-wire":"fixed-bls-wire";Pair oracle(f),changed(f);Bytes original=is_exit?encode_consensus_voluntary_exit_ssz(exit(f)):encode_capella_bls_change(change(f)),caller=original;bool mutated=false;size_t decoder_checks=0;if(is_exit)check(bool(decode_consensus_voluntary_exit_ssz(original,[&]{++decoder_checks;})),"exit decoder control");size_t calls=0;auto cb=[&]{checkpoint();if(++calls==decoder_checks+1){caller.back()^=1;mutated=true;}};const bool a=is_exit?oracle.node->voluntary_exit_ssz(original,checkpoint):oracle.node->bls_change_ssz(original,checkpoint);const bool b=is_exit?changed.node->voluntary_exit_ssz(caller,cb):changed.node->bls_change_ssz(caller,cb);check(a&&b&&mutated&&caller!=original,"authenticated original operation admitted across caller mutation");check(oracle.observation()==changed.observation(),"BLS/exit authentication and persisted wire must be the same owned original");changed.reopen();check(changed.observation()==oracle.observation(),"nonempty BLS/exit cold reopen original exact");Pair invalid(f);auto invalid_caller=original;std::fill(invalid_caller.end()-96,invalid_caller.end(),0);const auto invalid_before=invalid.observation();const auto invalid_files=invalid.physical();size_t invalid_calls=0;bool repaired=false;auto repair=[&]{checkpoint();if(++invalid_calls==decoder_checks+1){std::copy(original.begin(),original.end(),invalid_caller.begin());repaired=true;}};const bool accepted_invalid=is_exit?invalid.node->voluntary_exit_ssz(invalid_caller,repair):invalid.node->bls_change_ssz(invalid_caller,repair);check(repaired&&!accepted_invalid&&invalid.observation()==invalid_before&&invalid.physical()==invalid_files,"invalid original cannot be repaired by changing caller bytes after capture");}
