SyncInput sync_input(Pair& p){const auto slot=head_slot(p);const auto members=p.node->current_sync_members(slot,checkpoint);check(!members.empty(),"actual current sync committee");const auto index=*members.begin();const auto c=context(p);CapellaSyncMessage m{};m.slot=slot;m.validator_index=index;m.beacon_block_root=consensus_beacon_header_root(capella_fork_head(*p.node->current().state,p.f.rules,checkpoint)->header);const auto epoch=slot/p.f.rules.transition.consensus.epoch.ffg.slots_per_epoch;const auto version=epoch<c.fork.epoch?c.fork.previous_version:c.fork.current_version;test_copy(m.signature,TestKey(index).sign(consensus_signing_root(m.beacon_block_root,consensus_domain({7,0,0,0},version,c.genesis_root))));const auto h=capella_fork_head(*p.node->current().state,p.f.rules,checkpoint);const auto& t=p.f.rules.transition;auto state=prepare_capella_slots(h->state,{t.consensus.epoch,t.execution,t.maximum_state_bytes},t.consensus.state,slot+1,p.f.limits.replay_slots,p.f.limits.sync_trials,checkpoint);const auto& l=t.consensus.state;const size_t committee=272+64*l.slots_per_historical_root+32*l.epochs_per_historical_vector+8*l.epochs_per_slashings_vector+133,bit_bytes=(l.sync_committee_size+7)/8;Bytes aggregate(bit_bytes+96);std::vector<Bytes> signatures;TestKey key(index);for(size_t at=0;at<l.sync_committee_size;++at)if(std::equal(key.public_key.begin(),key.public_key.end(),state.ssz.begin()+committee+48*at)){aggregate[at/8]|=uint8_t(1u<<(at%8));signatures.emplace_back(m.signature.begin(),m.signature.end());}check(!signatures.empty(),"real repeated sync positions");auto sum=aggregate_consensus_bls_signatures(signatures);check(bool(sum),"real aggregate signature");std::copy(sum->begin(),sum->end(),aggregate.begin()+bit_bytes);return {m,aggregate};}
